-- LearnHub full schema for Supabase.
-- Generated by concatenating supabase/migrations/*.sql in order. Safe to re-run.
-- Use this when applying the schema manually (e.g. Supabase SQL editor).
-- Seed/sample data lives separately in supabase/seed.sql.

-- ===========================================================================
-- 20260101000000_init.sql
-- ===========================================================================

create table if not exists public.courses (
  id text primary key,
  title text not null,
  description text not null,
  instructor text not null,
  category text not null,
  level text not null,
  accent text not null,
  icon text not null
);

create table if not exists public.lessons (
  id text primary key,
  course_id text not null references public.courses (id) on delete cascade,
  sort_order integer not null,
  title text not null,
  summary text not null,
  duration integer not null,
  content text[] not null default '{}'
);

create index if not exists lessons_course_id_idx
  on public.lessons (course_id, sort_order);

create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  name text not null default '',
  email text not null default '',
  bio text not null default '',
  goal text not null default '',
  updated_at timestamptz not null default now()
);

create table if not exists public.user_settings (
  user_id uuid primary key references auth.users (id) on delete cascade,
  email_notifications boolean not null default true,
  weekly_reminder boolean not null default false,
  weekly_goal integer not null default 5,
  updated_at timestamptz not null default now()
);

create table if not exists public.lesson_progress (
  user_id uuid not null references auth.users (id) on delete cascade,
  lesson_id text not null references public.lessons (id) on delete cascade,
  status text not null check (status in ('in-progress', 'completed')),
  completed_at timestamptz,
  updated_at timestamptz not null default now(),
  primary key (user_id, lesson_id)
);

-- Row level security -------------------------------------------------------

alter table public.courses enable row level security;
alter table public.lessons enable row level security;
alter table public.profiles enable row level security;
alter table public.user_settings enable row level security;
alter table public.lesson_progress enable row level security;

drop policy if exists "courses are readable by everyone" on public.courses;
create policy "courses are readable by everyone"
  on public.courses for select
  using (true);

drop policy if exists "lessons are readable by everyone" on public.lessons;
create policy "lessons are readable by everyone"
  on public.lessons for select
  using (true);

drop policy if exists "own profile select" on public.profiles;
create policy "own profile select"
  on public.profiles for select
  using ((select auth.uid()) = id);

drop policy if exists "own profile insert" on public.profiles;
create policy "own profile insert"
  on public.profiles for insert
  with check ((select auth.uid()) = id);

drop policy if exists "own profile update" on public.profiles;
create policy "own profile update"
  on public.profiles for update
  using ((select auth.uid()) = id)
  with check ((select auth.uid()) = id);

drop policy if exists "own settings select" on public.user_settings;
create policy "own settings select"
  on public.user_settings for select
  using ((select auth.uid()) = user_id);

drop policy if exists "own settings insert" on public.user_settings;
create policy "own settings insert"
  on public.user_settings for insert
  with check ((select auth.uid()) = user_id);

drop policy if exists "own settings update" on public.user_settings;
create policy "own settings update"
  on public.user_settings for update
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

drop policy if exists "own progress select" on public.lesson_progress;
create policy "own progress select"
  on public.lesson_progress for select
  using ((select auth.uid()) = user_id);

drop policy if exists "own progress insert" on public.lesson_progress;
create policy "own progress insert"
  on public.lesson_progress for insert
  with check ((select auth.uid()) = user_id);

drop policy if exists "own progress update" on public.lesson_progress;
create policy "own progress update"
  on public.lesson_progress for update
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

drop policy if exists "own progress delete" on public.lesson_progress;
create policy "own progress delete"
  on public.lesson_progress for delete
  using ((select auth.uid()) = user_id);

-- Grants -------------------------------------------------------------------

grant usage on schema public to anon, authenticated;
grant select on public.courses to anon, authenticated;
grant select on public.lessons to anon, authenticated;
grant select, insert, update on public.profiles to authenticated;
grant select, insert, update on public.user_settings to authenticated;
grant select, insert, update, delete on public.lesson_progress to authenticated;

-- Create a profile and settings row for every new auth user -----------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, name, email, bio, goal)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'name', ''),
    coalesce(new.email, ''),
    '',
    'Complete all six courses this semester'
  )
  on conflict (id) do nothing;

  insert into public.user_settings (user_id)
  values (new.id)
  on conflict (user_id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ===========================================================================
-- 20260102000000_add_date_of_birth.sql
-- ===========================================================================

alter table public.profiles
  add column if not exists date_of_birth date;

-- Re-create the signup trigger so new profiles capture the date of birth
-- supplied during registration (stored in the auth user's metadata).
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, name, email, bio, goal, date_of_birth)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'name', ''),
    coalesce(new.email, ''),
    '',
    'Complete all six courses this semester',
    nullif(new.raw_user_meta_data ->> 'date_of_birth', '')::date
  )
  on conflict (id) do nothing;

  insert into public.user_settings (user_id)
  values (new.id)
  on conflict (user_id) do nothing;

  return new;
end;
$$;

-- ===========================================================================
-- 20260103000000_user_courses.sql
-- ===========================================================================

-- Per-student course ownership and editable course metadata.
--
-- Catalog courses keep owner_id = null and stay world-readable. Courses created
-- by a student get owner_id = auth.uid() and are only visible/editable by them.

alter table public.courses
  add column if not exists owner_id uuid references auth.users (id) on delete cascade,
  add column if not exists image_url text,
  add column if not exists total_lessons integer,
  add column if not exists start_date date,
  add column if not exists created_at timestamptz not null default now(),
  add column if not exists updated_at timestamptz not null default now();

-- Student-created courses do not provide level/accent/icon, so give defaults.
alter table public.courses alter column level set default 'Beginner';
alter table public.courses alter column accent set default 'indigo';
alter table public.courses alter column icon set default 'code';

alter table public.courses
  drop constraint if exists courses_total_lessons_check;
alter table public.courses
  add constraint courses_total_lessons_check
  check (total_lessons is null or total_lessons between 0 and 1000);

create index if not exists courses_owner_id_idx on public.courses (owner_id);

-- Ownership-aware row level security ---------------------------------------

drop policy if exists "courses are readable by everyone" on public.courses;

drop policy if exists "courses are readable by catalog or owner" on public.courses;
create policy "courses are readable by catalog or owner"
  on public.courses for select
  using (owner_id is null or (select auth.uid()) = owner_id);

drop policy if exists "owners can insert courses" on public.courses;
create policy "owners can insert courses"
  on public.courses for insert
  with check ((select auth.uid()) = owner_id);

drop policy if exists "owners can update courses" on public.courses;
create policy "owners can update courses"
  on public.courses for update
  using ((select auth.uid()) = owner_id)
  with check ((select auth.uid()) = owner_id);

drop policy if exists "owners can delete courses" on public.courses;
create policy "owners can delete courses"
  on public.courses for delete
  using ((select auth.uid()) = owner_id);

-- Grants -------------------------------------------------------------------

grant insert, update, delete on public.courses to authenticated;

-- ===========================================================================
-- 20260104000000_course_faculty_department.sql
-- ===========================================================================

-- Adds academic grouping to courses: faculty and department.
--
-- Catalog courses may leave these null; student-created courses set both.

alter table public.courses
  add column if not exists faculty text,
  add column if not exists department text;

create index if not exists courses_faculty_department_idx
  on public.courses (faculty, department);

-- ===========================================================================
-- 20260105000000_add_course_code.sql
-- ===========================================================================

-- Adds an optional course code (e.g. "SWE 201") to courses.
--
-- Catalog courses may leave this null; student-created courses can set it.

alter table public.courses
  add column if not exists course_code text;

-- ===========================================================================
-- 20260107000000_course_price.sql
-- ===========================================================================

-- Adds the course list price (in naira) shown alongside credit units.

alter table public.courses
  add column if not exists price integer not null default 0 check (price >= 0);

-- ===========================================================================
-- 20260108000000_material_progress.sql
-- ===========================================================================

-- Per-student reading progress for the "Learning Materials" feature. Course
-- materials are Markdown files served by authenticated API routes; this table
-- stores only completion state, keyed by user + course + lesson.

create table if not exists public.material_progress (
  user_id uuid not null references auth.users (id) on delete cascade,
  course_id text not null references public.courses (id) on delete cascade,
  lesson_id text not null,
  status text not null default 'completed'
    check (status in ('in-progress', 'completed')),
  completed_at timestamptz,
  updated_at timestamptz not null default now(),
  primary key (user_id, course_id, lesson_id)
);

create index if not exists material_progress_user_course_idx
  on public.material_progress (user_id, course_id);

alter table public.material_progress enable row level security;

drop policy if exists "own material progress select" on public.material_progress;
create policy "own material progress select"
  on public.material_progress for select
  using ((select auth.uid()) = user_id);

drop policy if exists "own material progress insert" on public.material_progress;
create policy "own material progress insert"
  on public.material_progress for insert
  with check ((select auth.uid()) = user_id);

drop policy if exists "own material progress update" on public.material_progress;
create policy "own material progress update"
  on public.material_progress for update
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

drop policy if exists "own material progress delete" on public.material_progress;
create policy "own material progress delete"
  on public.material_progress for delete
  using ((select auth.uid()) = user_id);

grant select, insert, update, delete on public.material_progress to authenticated;

-- ===========================================================================
-- 20260109000000_lesson_storage.sql
-- ===========================================================================

-- Stores each lesson body as a plain-text (.txt) file in a private Supabase
-- Storage bucket. Objects are laid out as "<course_id>/<file>.txt" so the
-- Storage policy can map a file back to its course and only allow enrolled
-- students, the course owner, or an administrator to read it.

alter table public.lessons
  add column if not exists storage_path text;

insert into storage.buckets (id, name, public)
values ('course-lessons', 'course-lessons', false)
on conflict (id) do nothing;

drop policy if exists "lesson files readable by enrolled students" on storage.objects;
create policy "lesson files readable by enrolled students"
  on storage.objects for select
  to authenticated
  using (
    bucket_id = 'course-lessons'
    and (
      public.is_admin((select auth.uid()))
      or exists (
        select 1 from public.courses c
        where c.id = split_part(name, '/', 1)
          and c.owner_id = (select auth.uid())
      )
      or exists (
        select 1 from public.registrations r
        where r.user_id = (select auth.uid())
          and r.course_id = split_part(name, '/', 1)
      )
    )
  );

drop policy if exists "lesson files writable by course owners" on storage.objects;
create policy "lesson files writable by course owners"
  on storage.objects for insert
  to authenticated
  with check (
    bucket_id = 'course-lessons'
    and (
      public.is_admin((select auth.uid()))
      or exists (
        select 1 from public.courses c
        where c.id = split_part(name, '/', 1)
          and c.owner_id = (select auth.uid())
      )
    )
  );

drop policy if exists "lesson files updatable by course owners" on storage.objects;
create policy "lesson files updatable by course owners"
  on storage.objects for update
  to authenticated
  using (
    bucket_id = 'course-lessons'
    and (
      public.is_admin((select auth.uid()))
      or exists (
        select 1 from public.courses c
        where c.id = split_part(name, '/', 1)
          and c.owner_id = (select auth.uid())
      )
    )
  )
  with check (
    bucket_id = 'course-lessons'
    and (
      public.is_admin((select auth.uid()))
      or exists (
        select 1 from public.courses c
        where c.id = split_part(name, '/', 1)
          and c.owner_id = (select auth.uid())
      )
    )
  );

drop policy if exists "lesson files removable by course owners" on storage.objects;
create policy "lesson files removable by course owners"
  on storage.objects for delete
  to authenticated
  using (
    bucket_id = 'course-lessons'
    and (
      public.is_admin((select auth.uid()))
      or exists (
        select 1 from public.courses c
        where c.id = split_part(name, '/', 1)
          and c.owner_id = (select auth.uid())
      )
    )
  );
